representative_cases.gold_plantuml:
start
if (slow charging is active) then(yes)
  :enter power-up mode;
  switch(condition judgement)
  case (remote mode is enabled)
    :switch to state 110;
    if (slow charging is inactive) then
      :switch to state 28;
      if (remote mode is disabled) then
      :shutdown;
      stop
      endif
    endif

  case (pet mode request is received)
    :switch to state 110;
    if (slow charging is inactive) then
      :switch to state 28;
      if (pet mode request handling is finished) then
      :shutdown;
      stop
      endif
    endif

  case (battery SOC is 20)
    :switch to state 110;
    if (slow charging is inactive) then
      :switch to state 28;
      if (battery SOC reaches 80 and DCDC state is 3) then
      :shutdown;
      stop
      endif
    endif

  endswitch
else(no)
  stop
endif
end

representative_cases.predicted_plantuml:
@startuml
start
:System Startup;
if (Slow charging active?) then (Yes)
  :Enter power-up mode;
  partition "Remote Mode Path" {
    if (Remote mode enabled?) then (Yes)
      :Enter state 110;
      if (Slow charging inactive?) then (Yes)
        :Go to state 28;
      endif
      if (Remote mode disabled?) then (Yes)
        :Shut down;
        end
      endif
    endif
  }
  partition "Pet Mode Path" {
    if (Pet mode request received?) then (Yes)
      :Switch to state 110;
      if (Slow charging inactive?) then (Yes)
        :Move to state 28;
      endif
      :Pet mode request handled;
      :Shut down;
      end
    endif
  }
  partition "Battery SOC Path" {
    if (Battery SOC == 20?) then (Yes)
      :Enter state 110;
      if (Slow charging inactive?) then (Yes)
        :Switch to state 28;
      endif
      if (SOC reaches 80 AND DCDC state == 3?) then (Yes)
        :Shut down;
        end
      endif
    endif
  }
endif
stop
@enduml
